import { useCallback, useEffect, useRef, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { useAuth } from "../auth/useAuth";
import { Activity, Archive, ArrowLeft, Bell, BookOpen, CalendarDays, ChartNoAxesCombined, Check, ClipboardList, FilePlus2, FileText, GraduationCap, LayoutDashboard, Eye, Inbox, LogOut, Medal, Menu, Moon, Pencil, Plus, RefreshCw, Search, Settings, Sun, Trash2, Trophy, UserCheck, UserX, Send, Users } from "lucide-react";
import { apiBaseUrl, lecturerRequest, sendJson } from "../services/lecturerApi";
import ProgressLineChart from "../components/ProgressLineChart";
import Toast from "../components/Toast";
import BarChart from "../components/BarChart";
import BarChartDataEditor from "../components/BarChartDataEditor";
import "./LecturerDashboard.css";

const NAV = [
  ["Dashboard", "/lecturer/dashboard", LayoutDashboard], ["My Exams", "/lecturer/exams", ClipboardList],
  ["Create Exam", "/lecturer/exams/create", FilePlus2], ["Question Bank", "/lecturer/question-bank", BookOpen],
  ["Exam Schedule", "/lecturer/schedule", CalendarDays], ["Exam Attempts", "/lecturer/attempts", Activity],
  ["Student Submissions", "/lecturer/submissions", FileText], ["Answer Evaluation", "/lecturer/evaluation", Check],
  ["Results & Grades", "/lecturer/results", GraduationCap], ["Performance Analytics", "/lecturer/analytics", ChartNoAxesCombined],
  ["Student Management", "/lecturer/students", Users], ["Notifications", "/lecturer/notifications", Bell],
  ["My Profile", "/lecturer/profile", Users], ["Settings", "/lecturer/settings", Settings],
];
const TITLES = Object.fromEntries(NAV.map(([title, path]) => [path, title]));
const date = (value) => value ? new Date(value).toLocaleString() : "—";
const dateOnly = (value) => value ? new Date(value).toLocaleDateString() : "—";
const readable = (value) => String(value || "—").replaceAll("_", " ").replace(/\b\w/g, (c) => c.toUpperCase());
const questionTypeLabel = (type) => ({ mcq: "Multiple Choice", true_false: "True / False", short_answer: "Short Answer", essay: "Essay / Structured", bar_chart: "Bar Chart Question" })[type] || readable(type);
const lecturerExamStatus = (exam) => exam.status !== "published" ? exam.status : new Date(exam.startsAt) > new Date() ? "scheduled" : new Date(exam.endsAt) > new Date() ? "ongoing" : "completed";

function Panel({ title, action, children, className = "" }) { return <section className={`lect-panel ${className}`}><div className="lect-panel-head"><h2>{title}</h2>{action}</div>{children}</section>; }
function Empty({ children = "Nothing to show yet." }) { return <div className="lect-empty">{children}</div>; }
function Status({ value }) { return <span className={`lect-status ${String(value || "draft").replaceAll("_", "-")}`}>{readable(value)}</span>; }
function Table({ columns, rows, empty, rowKey = (r, i) => r._id || r.id || i }) {
  if (!rows?.length) return <Empty>{empty || "No records found."}</Empty>;
  return <div className="lect-table-wrap"><table className="lect-table"><thead><tr>{columns.map((c) => <th key={c.label}>{c.label}</th>)}</tr></thead><tbody>{rows.map((row, i) => <tr key={rowKey(row, i)}>{columns.map((c) => <td key={c.label}>{c.render ? c.render(row) : row[c.key] ?? "—"}</td>)}</tr>)}</tbody></table></div>;
}

export default function LecturerDashboard({ theme, onToggleTheme }) {
  const location = useLocation(); const navigate = useNavigate();
  const { setAuthenticatedUser } = useAuth();
  const path = location.pathname.replace(/\/$/, "") || "/lecturer/dashboard";
  const participationExamId = path.match(/^\/lecturer\/exams\/([^/]+)\/participation$/)?.[1] || "";
  const [data, setData] = useState(null); const [busy, setBusy] = useState(true); const [error, setError] = useState(""); const [notice, setNotice] = useState("");
  const [refreshingExams, setRefreshingExams] = useState(false); const refreshingExamsRef = useRef(false);
  const [menuOpen, setMenuOpen] = useState(false); const [search, setSearch] = useState(""); const [filter, setFilter] = useState(""); const [page, setPage] = useState(1); const [analyticsSort, setAnalyticsSort] = useState("average"); const [editingId, setEditingId] = useState(""); const [editingQuestionId, setEditingQuestionId] = useState("");
  const savingExamRef = useRef(false); const [savingExam, setSavingExam] = useState(false);
  const [examForm, setExamForm] = useState({ title: "", module: "", description: "", instructions: "", category: "Examination", startsAt: "", endsAt: "", durationMinutes: 60, totalMarks: 0, maxAttempts: 1, eligibleStudents: [], questions: [], questionMarkAllocations: {}, randomizeQuestions: false, autoSubmit: true });
  const [questionForm, setQuestionForm] = useState({ text: "", type: "mcq", module: "", topic: "", difficulty: "medium", marks: 1, options: [{ key: "A", text: "" }, { key: "B", text: "" }], correctAnswer: "A", expectedAnswer: "", markingPoints: [], modelAnswer: "", rubric: [], chartData: [], allowNegative: false, markingGuide: "", explanation: "" });
  const submissionId = new URLSearchParams(location.search).get("submission") || "";
  const [profileForm, setProfileForm] = useState({ name: "", department: "" }); const [passwordForm, setPasswordForm] = useState({ currentPassword: "", newPassword: "" });

  const endpointFor = useCallback(() => {
    if (participationExamId) return `/exams/${participationExamId}/participation`;
    if (path === "/lecturer/dashboard") return "/dashboard";
    if (path === "/lecturer/exams" || path === "/lecturer/exams/create") return "/exams";
    if (path === "/lecturer/question-bank") return "/questions";
    if (path === "/lecturer/schedule") return "/schedule";
    if (path === "/lecturer/attempts") return "/attempts";
    if (path === "/lecturer/submissions" || path === "/lecturer/evaluation") return "/submissions";
    if (path === "/lecturer/results") return "/results";
    if (path === "/lecturer/analytics") return "/analytics";
    if (path === "/lecturer/students") return "/students";
    if (path === "/lecturer/notifications") return "/notifications";
    if (path === "/lecturer/profile") return "/profile";
    return "/dashboard";
  }, [path, participationExamId]);

  const load = useCallback(async ({ silent = false } = {}) => {
    if (!silent) setBusy(true); setError("");
    try {
      const [payload, profile] = await Promise.all([
        lecturerRequest(`${endpointFor()}${path === "/lecturer/exams" ? `?${new URLSearchParams({ page: String(page), limit: "15", sort: "date_desc", ...(search ? { search } : {}), ...(filter ? { status: filter } : {}) })}` : path === "/lecturer/analytics" ? `?${new URLSearchParams({ page: String(page), limit: "10", sort: analyticsSort, ...(search ? { search } : {}) })}` : path === "/lecturer/question-bank" && (search || filter) ? `?${new URLSearchParams({ search, ...(filter ? { type: filter } : {}) })}` : path === "/lecturer/students" && search ? `?${new URLSearchParams({ search })}` : ""}`),
        path === "/lecturer/dashboard" || participationExamId ? Promise.resolve(null) : lecturerRequest("/profile"),
      ]);
      if (path === "/lecturer/exams/create") {
        const [questionData, studentData] = await Promise.all([lecturerRequest("/questions"), lecturerRequest("/eligible-students")]);
        payload.questions = questionData.items || [];
        payload.students = studentData.items || [];
      }
      setData(payload);
      if (profile) payload.profile = payload.profile || profile;
      const p = payload.profile || profile;
      if (p) setProfileForm({ name: p.name || "", department: p.department || "" });
      if (path === "/lecturer/exams/create" && payload.items) {
        const id = new URLSearchParams(location.search).get("edit");
        if (id && id !== editingId) {
          const detail = await lecturerRequest(`/exams/${id}`); const e = detail.exam;
          setExamForm({ ...e, startsAt: e.startsAt?.slice(0, 16), endsAt: e.endsAt?.slice(0, 16), eligibleStudents: e.eligibleStudents?.map((s) => String(s._id)) || [], questions: e.questions?.map((q) => String(q._id)) || [], questionMarkAllocations: Object.fromEntries((e.questionSnapshots||[]).map(q=>[String(q.originalQuestion),q.marks])) }); setEditingId(id);
        }
      }
      if ((path === "/lecturer/evaluation" || path === "/lecturer/submissions") && submissionId) {
        const detail = await lecturerRequest(`/submissions/${submissionId}`); setData((old) => ({ ...old, selectedSubmission: detail.submission }));
      }
      return true;
    } catch (e) { setError(e.message || "Unable to load this page."); return false; }
    finally { if (!silent) setBusy(false); }
  }, [endpointFor, path, participationExamId, search, filter, page, analyticsSort, location.search, editingId, submissionId]);
  useEffect(() => { const timer = window.setTimeout(load, 180); return () => window.clearTimeout(timer); }, [load]);

  const act = async (fn, success) => { setError(""); setNotice(""); try { await fn(); setNotice(success); await load(); } catch (e) { setError(e.message || "Action failed."); } };
  const refreshExams = async () => {
    if (refreshingExamsRef.current) return;
    refreshingExamsRef.current = true; setRefreshingExams(true); setNotice("");
    try { if (await load({ silent: true })) setNotice("Exam list refreshed."); }
    finally { refreshingExamsRef.current = false; setRefreshingExams(false); }
  };
  const saveExam = async (publish = false) => {
    if (savingExamRef.current) return; savingExamRef.current = true; setSavingExam(true);
    try { const body = { ...examForm, totalMarks: Number(examForm.totalMarks), durationMinutes: Number(examForm.durationMinutes), maxAttempts: Number(examForm.maxAttempts), startsAt: new Date(examForm.startsAt).toISOString(), endsAt: new Date(examForm.endsAt).toISOString() }; await act(async () => { const result = editingId ? await lecturerRequest(`/exams/${editingId}`, sendJson("PATCH", body)) : await lecturerRequest("/exams", sendJson("POST", body)); const id = editingId || result.exam._id; if (publish) await lecturerRequest(`/exams/${id}/publish`, sendJson("POST", {})); setEditingId(""); navigate("/lecturer/exams"); }, publish ? "Exam published successfully." : "Exam draft saved."); } catch (e) { setError(e.message || "Unable to save exam."); } finally { savingExamRef.current = false; setSavingExam(false); }
  };
  const saveQuestion = async (event) => {
    event.preventDefault();
    const marks = Number(questionForm.marks);
    const criteria = questionForm.type === "short_answer" ? questionForm.markingPoints : questionForm.type === "essay" ? questionForm.rubric : [];
    if (!questionForm.text.trim() || !questionForm.module.trim() || !Number.isFinite(marks) || marks <= 0) { setError("Enter question text, module, and positive total marks."); return; }
    if (questionForm.type === "mcq" && (questionForm.options.length < 2 || questionForm.options.some((option) => !option.text.trim()) || !questionForm.options.some((option) => option.key === questionForm.correctAnswer))) { setError("Add at least two non-empty options and select the correct answer."); return; }
    if (questionForm.type === "true_false" && !["true", "false"].includes(String(questionForm.correctAnswer).toLowerCase())) { setError("Select True or False as the correct answer."); return; }
    if (criteria.length && (criteria.some((item) => !item.description.trim() || !Number.isFinite(Number(item.marks)) || Number(item.marks) <= 0) || Math.abs(criteria.reduce((sum, item) => sum + Number(item.marks), 0) - marks) > 0.001)) { setError("Each criterion needs a description and positive marks, and the criterion marks must equal the question total."); return; }
    if (questionForm.type === "short_answer" && criteria.length === 0) { setError("Add at least one short-answer marking point."); return; }
    if (questionForm.type === "essay" && criteria.length === 0) { setError("Add at least one essay rubric criterion."); return; }
    if (questionForm.type === "bar_chart") {
      const bars = questionForm.chartData || [];
      const categories = bars.map((bar) => String(bar.category || "").trim().toLocaleLowerCase());
      if (!bars.length || bars.length > 20 || bars.some((bar) => !String(bar.category || "").trim() || !Number.isFinite(Number(bar.value)) || (bar.value === "" || bar.value === null || bar.value === undefined) || (!questionForm.allowNegative && Number(bar.value) < 0))) { setError("Add 1–20 reference bars with a category and valid value before saving."); return; }
      if (new Set(categories).size !== categories.length) { setError("Reference bar category names must be unique."); return; }
    }
    setError("");
    const payload = { ...questionForm, marks, chartData: questionForm.chartData.map((bar) => ({ category: bar.category.trim(), value: Number(bar.value) })), markingPoints: questionForm.markingPoints.map((point) => ({ ...point, marks: Number(point.marks) })), rubric: questionForm.rubric.map((point) => { const savedPoint = { ...point }; delete savedPoint._uiKey; return { ...savedPoint, marks: Number(point.marks) }; }) };
    setError(""); setNotice("");
    try {
      const result = await lecturerRequest(editingQuestionId ? `/questions/${editingQuestionId}` : "/questions", sendJson(editingQuestionId ? "PATCH" : "POST", payload));
      const saved = result.question;
      setData((old) => ({ ...old, items: [saved, ...(old?.items || []).filter((item) => String(item._id) !== String(saved._id))] }));
      setSearch(""); setFilter(""); setEditingQuestionId("");
      setQuestionForm({ text: "", type: "mcq", module: "", topic: "", difficulty: "medium", marks: 1, options: [{ key: "A", text: "" }, { key: "B", text: "" }], correctAnswer: "A", expectedAnswer: "", markingPoints: [], modelAnswer: "", rubric: [], chartData: [], allowNegative: false, markingGuide: "", explanation: "" });
      setNotice(editingQuestionId ? "Question updated." : "Question saved to your bank.");
    } catch (error) { setError(error.message || "Unable to save question. Your form values are still available."); }
  };
  const logout = async () => { setError(""); try { const response = await fetch(`${apiBaseUrl}/api/auth/logout`, { method: "POST", credentials: "include" }); const payload = await response.json().catch(() => ({})); if (!response.ok) throw new Error(payload.message || "The server could not end this session."); setAuthenticatedUser(null); navigate("/signin", { replace: true }); } catch (e) { setError(e.message || "Unable to end this session."); } };
  const title = participationExamId ? "Exam Student Participation" : TITLES[path] || (path === "/lecturer/exams/create" ? "Create Exam" : "Lecturer Portal");
  const active = participationExamId ? "/lecturer/exams" : path === "/lecturer/exams/create" ? "/lecturer/exams/create" : path;

  const content = (() => {
    if (busy) return <div className="lect-skeleton" role="status"><i/><i/><i/></div>;
    if (participationExamId && String(data?.exam?._id || "") !== participationExamId) {
      if (error) return <div className="lect-error" role="alert">{error}<button onClick={load}>Retry</button></div>;
      return <div className="lect-skeleton" role="status"><i/><i/><i/></div>;
    }
    if (error && !data) return <div className="lect-error" role="alert">{error}<button onClick={load}>Retry</button></div>;
    if (participationExamId) return <Participation data={data} onRefresh={load} navigate={navigate}/>;
    if (path === "/lecturer/dashboard") return <Dashboard data={data} navigate={navigate}/>;
    if (path === "/lecturer/exams") return <Exams data={data} search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} act={act} navigate={navigate} page={page} setPage={setPage}/>;
    if (path === "/lecturer/exams/create") return <ExamEditor form={examForm} setForm={setExamForm} data={data} editing={Boolean(editingId)} saving={savingExam} saveExam={saveExam} cancel={() => { setEditingId(""); navigate("/lecturer/exams"); }} />;
    if (path === "/lecturer/question-bank") return <Questions key={data?.items?.[0]?._id || "question-bank"} data={data} form={questionForm} setForm={setQuestionForm} save={saveQuestion} editingId={editingQuestionId} setEditingId={setEditingQuestionId} search={search} setSearch={setSearch} filter={filter} setFilter={setFilter} act={act} load={load}/>;
    if (path === "/lecturer/schedule") return <Schedule data={data} navigate={navigate}/>;
    if (path === "/lecturer/attempts") return <Attempts data={data} navigate={navigate}/>;
    if (path === "/lecturer/submissions" || path === "/lecturer/evaluation") return <Submissions data={data} selected={data?.selectedSubmission} navigate={navigate} location={location} act={act} evaluation={path.endsWith("evaluation")}/>;
    if (path === "/lecturer/results") return <Results data={data} act={act}/>;
    if (path === "/lecturer/analytics") return <Analytics data={data} search={search} setSearch={(value) => { setSearch(value); setPage(1); }} page={page} setPage={setPage} sort={analyticsSort} setSort={(value) => { setAnalyticsSort(value); setPage(1); }}/>;
    if (path === "/lecturer/students") return <Students data={data} search={search} setSearch={setSearch}/>;
    if (path === "/lecturer/notifications") return <Notifications data={data} act={act}/>;
    if (path === "/lecturer/profile") return <Profile profile={profileForm} setProfile={setProfileForm} act={act}/>;
    if (path === "/lecturer/settings") return <SettingsPage theme={theme} onToggleTheme={onToggleTheme} password={passwordForm} setPassword={setPasswordForm} act={act} logout={logout}/>;
    return <Panel title="Page not found"><Empty>This Lecturer Portal page does not exist.</Empty><Link to="/lecturer/dashboard">Return to dashboard</Link></Panel>;
  })();

  return <div className="lect-app">
    <aside className={`lect-sidebar ${menuOpen ? "open" : ""}`}>
      <Link to="/lecturer/dashboard" className="lect-brand" onClick={() => setMenuOpen(false)}>
        <img src={`${import.meta.env.BASE_URL}examora-logo.jpeg`} alt="" />
        <span>Examora<small>LECTURER PORTAL</small></span>
      </Link>
      <div className="lect-nav-caption">WORKSPACE</div>
      <nav aria-label="Lecturer navigation">{NAV.map(([name, href, Icon]) => <Link key={href} to={href} onClick={() => setMenuOpen(false)} className={`lect-nav ${active === href ? "active" : ""}`} aria-current={active === href ? "page" : undefined}><Icon size={17} strokeWidth={1.8}/><span>{name}</span>{name === "Notifications" && data?.stats?.unreadNotifications > 0 && <b>{data.stats.unreadNotifications > 9 ? "9+" : data.stats.unreadNotifications}</b>}</Link>)}</nav>
      <div className="lect-user">
        <div className="lect-avatar">{(data?.profile?.name || "L").slice(0, 1).toUpperCase()}</div>
        <span><b>{data?.profile?.name || "Lecturer"}</b><small>{data?.profile?.email || ""}</small></span>
        <button type="button" className="lect-logout" onClick={logout} aria-label="Log out" title="Log out"><LogOut size={16}/></button>
      </div>
    </aside>
    {menuOpen && <button className="lect-backdrop" aria-label="Close navigation" onClick={() => setMenuOpen(false)}/>}
    <div className="lect-main">
      <header className="lect-topbar">
        <button type="button" className="lect-menu" onClick={() => setMenuOpen(!menuOpen)} aria-label="Toggle navigation"><Menu size={20}/></button>
        <div className="lect-breadcrumb"><span>EXAMORA</span><b>/</b>{title}</div>
        <div className="lect-top-actions">
          <span className="lect-date">{new Intl.DateTimeFormat(undefined, { dateStyle: "medium" }).format(new Date())}</span>
          <button type="button" className="lect-theme-toggle" onClick={onToggleTheme} aria-label={`Switch to ${theme === "light" ? "dark" : "light"} mode`} title={`Switch to ${theme === "light" ? "dark" : "light"} mode`}>{theme === "light" ? <Moon size={17}/> : <Sun size={17}/>}</button>
          <Link to="/lecturer/notifications" className="lect-notification-link" aria-label={`${data?.stats?.unreadNotifications || 0} unread notifications`}><Bell size={17}/>{data?.stats?.unreadNotifications > 0 && <i>{data.stats.unreadNotifications > 9 ? "9+" : data.stats.unreadNotifications}</i>}</Link>
        </div>
      </header>
      <main className="lect-page-content">
        {error && data && <Toast key={`error:${error}`} message={error} type="error" onClose={() => setError("")} />}
        {notice && <Toast key={`success:${notice}`} message={notice} type="success" onClose={() => setNotice("")} />}
        {path === "/lecturer/dashboard" && data?.profile ? <section className="lect-welcome-band"><div className="lect-welcome-copy"><span className="lect-eyebrow">LECTURER OVERVIEW</span><h1>Welcome back, {data.profile.name || "Lecturer"}</h1><p>Your teaching workspace for exams, student submissions, and results.</p><time>{new Intl.DateTimeFormat(undefined, { dateStyle: "full" }).format(new Date())}</time></div><div className="lect-welcome-brand" aria-label="Examora Lecturer Portal"><span className="lect-welcome-logo" aria-hidden="true"><svg viewBox="0 0 56 56" fill="none"><defs><linearGradient id="examora-mark-gradient" x1="7" y1="5" x2="49" y2="52" gradientUnits="userSpaceOnUse"><stop stopColor="#AFC5FF"/><stop offset="1" stopColor="#8076E8"/></linearGradient></defs><rect x="2" y="2" width="52" height="52" rx="16" fill="url(#examora-mark-gradient)"/><path d="M18 14.5h13l9 9v17a2.5 2.5 0 0 1-2.5 2.5h-19a2.5 2.5 0 0 1-2.5-2.5V17a2.5 2.5 0 0 1 2.5-2.5Z" fill="#F8FAFF" fillOpacity=".97"/><path d="M30 14.5V23h9" stroke="#6478C8" strokeWidth="2" strokeLinejoin="round"/><path d="m21 32 4.1 4.1L34 27" stroke="#39765C" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/><path d="m14 14 14-6 14 6-14 6-14-6Z" fill="#263F78" stroke="#F8FAFF" strokeWidth="1.5" strokeLinejoin="round"/><path d="M19 16.5v5c0 2.8 4 5 9 5s9-2.2 9-5v-5" stroke="#F8FAFF" strokeWidth="1.5" strokeLinecap="round"/><path d="M42 15v8" stroke="#F8FAFF" strokeWidth="1.5" strokeLinecap="round"/><circle cx="42" cy="25" r="1.5" fill="#F8FAFF"/></svg></span><span className="lect-welcome-wordmark"><strong>Examora</strong><small>LECTURER PORTAL</small></span></div></section> : <div className="lect-page-intro"><div><p>EXAMORA · LECTURER WORKSPACE</p><h1>{title}</h1><span>{participationExamId ? "Review eligible students, exam attempts, and submission progress." : descriptionFor(path)}</span></div><div className="lect-page-actions">{participationExamId && <Link className="lect-secondary" to="/lecturer/exams"><ArrowLeft size={15}/> Back to My Exams</Link>}{path === "/lecturer/exams" && <button type="button" className="lect-secondary lect-refresh-button" onClick={refreshExams} disabled={refreshingExams} aria-busy={refreshingExams}><RefreshCw size={15} className={refreshingExams ? "lect-spin" : ""}/>{refreshingExams ? "Refreshing…" : "Refresh"}</button>}{!participationExamId && path !== "/lecturer/exams/create" && <Link className="lect-primary" to="/lecturer/exams/create"><Plus size={16}/> Create exam</Link>}</div></div>}
        {content}
      </main>
    </div>
  </div>;
}

function descriptionFor(path) { return ({ "/lecturer/dashboard": "Your examination activity and the work that needs your attention.", "/lecturer/exams": "Create, schedule, and manage examinations you own.", "/lecturer/exams/create": "Configure timing, eligibility, and questions for an exam.", "/lecturer/question-bank": "Build reusable questions for your examinations.", "/lecturer/schedule": "Review your scheduled, active, and completed exams.", "/lecturer/attempts": "Inspect attempts recorded for your examinations.", "/lecturer/submissions": "Review student answers and marking status.", "/lecturer/evaluation": "Grade manual responses and review automatic marking.", "/lecturer/results": "Review completed evaluations and publish official results.", "/lecturer/analytics": "Participation and published mark summaries from your exams.", "/lecturer/students": "Students who are eligible for examinations you manage.", "/lecturer/notifications": "Submission activity, reminders, and result updates.", "/lecturer/profile": "Manage your lecturer profile information.", "/lecturer/settings": "Security and session preferences." })[path] || "Manage your lecturer workspace."; }

function Dashboard({ data, navigate }) {
  const s = data?.stats || {}; const cards = [["Total exams", s.total, ClipboardList], ["Draft exams", s.draft, FileText], ["Published", s.published, Check], ["Upcoming", s.upcoming, CalendarDays], ["Ongoing", s.ongoing, Activity], ["Completed", s.completed, Archive], ["To evaluate", s.pendingEvaluation, Pencil], ["Published results", s.publishedResults, GraduationCap]];
  return <div className="lect-dashboard"><section className="lect-stat-grid lect-dashboard-stats">{cards.map(([label, value, Icon]) => <article className="lect-stat" key={label}><span>{label}</span><Icon size={18}/><strong>{value ?? 0}</strong><small>Live database count</small></article>)}</section>
    <div className="lect-columns lect-dashboard-sections"><Panel title="Upcoming examination schedule" action={<button type="button" className="lect-dashboard-action" onClick={() => navigate("/lecturer/schedule")}><CalendarDays size={14}/> Full schedule</button>}><Table rows={data?.upcoming} empty="No upcoming published exams." columns={[{label:"Exam",render:r=><b>{r.title}</b>},{label:"Module",key:"module"},{label:"Starts",render:r=>date(r.startsAt)},{label:"Duration",render:r=>`${r.durationMinutes} min`},{label:"Status",render:r=><Status value={r.status}/>}]}/></Panel>
      <Panel title="Recent submissions" action={<button type="button" className="lect-dashboard-action" onClick={() => navigate("/lecturer/submissions")}><ClipboardList size={14}/> View all</button>}><Table rows={data?.recentAttempts} empty="No student attempts recorded." columns={[{label:"Student",render:r=><>{r.student}<small className="lect-sub">{r.studentId || ""}</small></>},{label:"Exam",key:"exam"},{label:"Status",render:r=><Status value={r.evaluationStatus || r.status}/>} ]}/></Panel>
      <Panel title="Recently managed exams"><Table rows={data?.exams} columns={[{label:"Examination",key:"title"},{label:"Module",key:"module"},{label:"Status",render:r=><Status value={r.status}/>},{label:"Updated",render:r=>dateOnly(r.updatedAt)}]} empty="Create your first exam to get started."/></Panel>
      <Panel title="Notifications" action={<button type="button" className="lect-dashboard-action" onClick={() => navigate("/lecturer/notifications")}><Inbox size={14}/> Open inbox</button>}>{data?.notifications?.length ? data.notifications.slice(0,4).map((n)=><div className="lect-notice-row" key={n._id}><span className="lect-dot"/><div><b>{n.title}</b><p>{n.message}</p><small>{date(n.createdAt)}</small></div></div>) : <Empty>No lecturer notifications yet.</Empty>}</Panel>
      <Panel title="Submission and marking progress"><div className="lect-progress-row"><span>Submitted attempts <b>{s.submittedAttempts || 0} / {s.totalAttempts || 0}</b></span><div><i style={{width:`${s.totalAttempts ? Math.round(100*s.submittedAttempts/s.totalAttempts) : 0}%`}}/></div></div><div className="lect-progress-row"><span>Evaluated attempts <b>{s.evaluatedAttempts || 0} / {s.submittedAttempts || 0}</b></span><div><i style={{width:`${s.submittedAttempts ? Math.round(100*s.evaluatedAttempts/s.submittedAttempts) : 0}%`}}/></div></div><div className="lect-quick-links"><Link to="/lecturer/exams/create"><Plus size={15}/> Create exam</Link><Link to="/lecturer/question-bank"><BookOpen size={15}/> Add questions</Link><Link to="/lecturer/evaluation"><Pencil size={15}/> Evaluate work</Link><Link to="/lecturer/results"><GraduationCap size={15}/> Publish results</Link></div></Panel></div>
  </div>;
}

function Exams({ data, search, setSearch, filter, setFilter, act, navigate, page, setPage }) {
  const rows = data?.items || [];
  const actions = (e) => <div className="lect-row-actions">{e.status === "draft" && <><button title="Edit draft" onClick={() => navigate(`/lecturer/exams/create?edit=${e._id}`)}><Pencil size={15}/></button><button title="Publish" onClick={() => act(() => lecturerRequest(`/exams/${e._id}/publish`, sendJson("POST", {})), "Exam published.")}><Check size={15}/></button><button title="Delete draft" onClick={() => window.confirm("Delete this draft exam?") && act(() => lecturerRequest(`/exams/${e._id}`, { method:"DELETE" }), "Draft deleted.")}><Trash2 size={15}/></button></>}{e.status === "published" && <button title="Archive" onClick={() => act(() => lecturerRequest(`/exams/${e._id}/archive`, sendJson("POST", {})), "Exam archived.")}><Archive size={15}/></button>}<button title="Duplicate to draft" onClick={() => act(async () => { const body = {...e, title:`${e.title} (Copy)`, questions:e.questions.map(q=>q._id), eligibleStudents:e.eligibleStudents.map(s=>s._id)}; delete body._id; delete body.createdAt; delete body.updatedAt; await lecturerRequest("/exams", sendJson("POST", body)); }, "Draft copy created.")}><Plus size={15}/></button></div>;
  return <Panel title="Exam management"><div className="lect-toolbar"><label className="lect-search"><Search size={16}/><input value={search} onChange={e=>{setSearch(e.target.value);setPage(1);}} placeholder="Search exam or module"/></label><select aria-label="Filter exam status" value={filter} onChange={e=>{setFilter(e.target.value);setPage(1);}}><option value="">All statuses</option>{["draft","published","scheduled","ongoing","completed","archived"].map(s=><option key={s} value={s}>{readable(s)}</option>)}</select></div><Table rows={rows} columns={[{label:"Exam",render:r=><><Link className="lect-exam-name" to={`/lecturer/exams/${r._id}/participation`}>{r.title}</Link><small className="lect-sub">{r.category || "Examination"}</small></>},{label:"Module",key:"module"},{label:"Schedule",render:r=>date(r.startsAt)},{label:"Students",render:r=>r.eligibleStudents?.length ?? 0},{label:"Attempts",key:"attemptCount"},{label:"Status",render:r=><Status value={lecturerExamStatus(r)}/>},{label:"Actions",render:actions}]} empty="No exams match your filters."/><div className="lect-page-controls"><span>Page {data?.page||page} of {data?.pages||1} · {data?.total||0} exams</span><button className="lect-secondary" disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</button><button className="lect-secondary" disabled={page>=(data?.pages||1)} onClick={()=>setPage(page+1)}>Next</button></div></Panel>;
}

function Participation({ data, onRefresh, navigate }) {
  const [attemptedSearch, setAttemptedSearch] = useState("");
  const [notAttemptedSearch, setNotAttemptedSearch] = useState("");
  const [statusFilter, setStatusFilter] = useState("");
  const [attemptSort, setAttemptSort] = useState("name");
  const [notAttemptedSort, setNotAttemptedSort] = useState("name");
  const [refreshing, setRefreshing] = useState(false);
  const exam = data?.exam;
  const summary = data?.summary || {};
  const matches = (student, value) => {
    const query = value.trim().toLocaleLowerCase();
    return !query || [student.studentId, student.name, student.email].some((field) => String(field || "").toLocaleLowerCase().includes(query));
  };
  const evaluationLabel = (value) => ({ not_started: "Evaluation Pending", pending: "Evaluation Pending", partial: "Evaluation Pending", evaluated: "Evaluated", finalized: "Finalized" })[value] || "";
  const normalizedEvaluationStatus = (value) => ["not_started", "pending", "partial"].includes(value) ? "pending" : value;
  const attempted = (data?.attemptedStudents || []).filter((student) => matches(student, attemptedSearch) && (!statusFilter || student.attemptStatus === statusFilter || student.evaluationStatus === statusFilter || statusFilter === "pending" && ["not_started", "partial"].includes(student.evaluationStatus)))
    .sort((a, b) => attemptSort === "name" ? a.name.localeCompare(b.name) : attemptSort === "oldest" ? new Date(a.startedAt || 0) - new Date(b.startedAt || 0) : new Date(b.startedAt || 0) - new Date(a.startedAt || 0));
  const notAttempted = (data?.notAttemptedStudents || []).filter((student) => matches(student, notAttemptedSearch))
    .sort((a, b) => notAttemptedSort === "id" ? String(a.studentId || "").localeCompare(String(b.studentId || "")) : a.name.localeCompare(b.name));
  const refresh = async () => {
    if (refreshing) return;
    setRefreshing(true);
    try { await onRefresh({ silent: true }); }
    finally { setRefreshing(false); }
  };
  const stats = [["Total eligible", summary.totalEligible, Users, "Active and assigned"], ["Attempted", summary.attempted, UserCheck, "At least one attempt"], ["Not attempted", summary.notAttempted, UserX, "No attempt recorded"], ["Submitted", summary.submitted, Send, "Successfully submitted"]];
  return <div className="lect-participation">
    <Panel title="Examination details" className="lect-participation-exam" action={<button type="button" className="lect-secondary lect-refresh-button" onClick={refresh} disabled={refreshing} aria-busy={refreshing}><RefreshCw size={15} className={refreshing ? "lect-spin" : ""}/>{refreshing ? "Refreshing…" : "Refresh"}</button>}>
      <div className="lect-participation-heading"><div><span className="lect-participation-eyebrow">SELECTED EXAMINATION</span><h2>{exam?.title || "Examination"}</h2><p>{exam?.module || "Module not provided"}</p></div><Status value={lecturerExamStatus(exam || {})}/></div>
      <dl className="lect-exam-meta"><div><dt>Examination date</dt><dd>{dateOnly(exam?.startsAt)}</dd></div><div><dt>Start time</dt><dd>{exam?.startsAt ? new Date(exam.startsAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" }) : "—"}</dd></div><div><dt>Duration</dt><dd>{exam?.durationMinutes ? `${exam.durationMinutes} minutes` : "—"}</dd></div><div><dt>Maximum marks</dt><dd>{exam?.totalMarks ?? "—"}</dd></div><div><dt>Closes</dt><dd>{date(exam?.endsAt)}</dd></div></dl>
    </Panel>
    <section className="lect-stat-grid compact lect-participation-stats" aria-label="Participation summary">{stats.map(([label, value, Icon, detail]) => <article className="lect-stat" key={label}><span>{label}</span><Icon size={18}/><strong>{value ?? 0}</strong><small>{detail}</small></article>)}</section>
    <Panel title="Student participation summary" className="lect-participation-summary"><div className="lect-participation-rate"><div><span>Submission rate</span><strong>{Number(summary.submissionRate || 0).toFixed(1)}%</strong><small>{summary.submitted || 0} submitted of {summary.totalEligible || 0} eligible students</small></div><div className="lect-participation-progress" role="progressbar" aria-label="Submission rate" aria-valuemin="0" aria-valuemax="100" aria-valuenow={Math.min(100, Math.max(0, summary.submissionRate || 0))}><i style={{ width: `${Math.min(100, Math.max(0, summary.submissionRate || 0))}%` }}/></div></div></Panel>
    <Panel title={`Attempted Students · ${summary.attempted || 0}`} className="lect-participation-list" action={<span className="lect-participation-section-count">Started an attempt</span>}>
      <div className="lect-toolbar lect-participation-toolbar"><label className="lect-search"><Search size={16}/><input value={attemptedSearch} onChange={(event) => setAttemptedSearch(event.target.value)} placeholder="Search ID, name, or email" aria-label="Search attempted students"/></label><select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)} aria-label="Filter attempted students by status"><option value="">All attempt statuses</option><option value="in_progress">In Progress</option><option value="submitted">Submitted</option><option value="expired">Expired</option><option value="pending">Evaluation Pending</option><option value="evaluated">Evaluated</option><option value="finalized">Finalized</option></select><select value={attemptSort} onChange={(event) => setAttemptSort(event.target.value)} aria-label="Sort attempted students"><option value="name">Sort by student name</option><option value="newest">Newest attempt</option><option value="oldest">Oldest attempt</option></select></div>
      <Table rows={attempted} empty={summary.attempted ? "No attempted students match this search or filter." : "No students have started this examination yet."} columns={[{label:"Student ID",render:(student)=>student.studentId||"—"},{label:"Student name",render:(student)=><b>{student.name}</b>},{label:"Email address",key:"email"},{label:"Attempt status",render:(student)=><span className="lect-participation-badges"><Status value={student.attemptStatus}/>{evaluationLabel(student.evaluationStatus)&&<Status value={normalizedEvaluationStatus(student.evaluationStatus)}/>}</span>},{label:"Started at",render:(student)=>date(student.startedAt)},{label:"Submitted at",render:(student)=>date(student.submittedAt)},{label:"Actions",render:(student)=><button type="button" className="lect-secondary lect-participation-view" onClick={()=>navigate(`/lecturer/submissions?submission=${encodeURIComponent(student.attemptId)}`)}>View attempt</button>}]}/>
    </Panel>
    <Panel title={`Not Attempted Students · ${summary.notAttempted || 0}`} className="lect-participation-list" action={<span className="lect-participation-section-count">Eligible · no attempt recorded</span>}>
      <div className="lect-toolbar lect-participation-toolbar"><label className="lect-search"><Search size={16}/><input value={notAttemptedSearch} onChange={(event) => setNotAttemptedSearch(event.target.value)} placeholder="Search ID, name, or email" aria-label="Search not attempted students"/></label><select value={notAttemptedSort} onChange={(event) => setNotAttemptedSort(event.target.value)} aria-label="Sort not attempted students"><option value="name">Sort by student name</option><option value="id">Sort by student ID</option></select></div>
      <Table rows={notAttempted} empty={summary.notAttempted ? "No students match this search." : "All eligible students have started an attempt."} columns={[{label:"Student ID",render:(student)=>student.studentId||"—"},{label:"Student name",render:(student)=><b>{student.name}</b>},{label:"Email address",key:"email"},{label:"Account status",render:()=> <Status value="active"/>}]}/>
    </Panel>
  </div>;
}

function ExamEditor({ form, setForm, data, editing, saving, saveExam, cancel }) {
  const patch = (key, value) => setForm((old)=>({...old,[key]:value})); const questions = data?.questions || []; const students = data?.students || []; const [query,setQuery]=useState(""); const [type,setType]=useState(""); const [difficulty,setDifficulty]=useState(""); const [moduleFilter,setModuleFilter]=useState("");
  const selected = questions.filter(q=>form.questions.includes(String(q._id))); const toggle=(id)=>setForm(old=>{const ids=old.questions.includes(id)?old.questions.filter(x=>x!==id):[...old.questions,id];const allocations={...(old.questionMarkAllocations||{})};if(ids.includes(id))allocations[id]=Number(questions.find(q=>String(q._id)===id)?.marks||1);else delete allocations[id];return {...old,questions:ids,questionMarkAllocations:allocations,totalMarks:questions.filter(q=>ids.includes(String(q._id))).reduce((s,q)=>s+Number(allocations[String(q._id)]??q.marks),0)};});
  const setQuestionMarks=(id,value)=>setForm(old=>{const allocations={...(old.questionMarkAllocations||{}),[id]:Number(value)};return {...old,questionMarkAllocations:allocations,totalMarks:questions.filter(q=>old.questions.includes(String(q._id))).reduce((s,q)=>s+Number(allocations[String(q._id)]??q.marks),0)};});
  return <Panel title={editing ? "Edit draft exam" : "New examination"}><form className="lect-form" onSubmit={e=>{e.preventDefault();saveExam(false);}}>
    <h3>Basic information</h3><div className="lect-form-grid"><label>Exam title<input required maxLength="180" value={form.title} onChange={e=>patch("title",e.target.value)}/></label><label>Subject / module<input required maxLength="120" value={form.module} onChange={e=>patch("module",e.target.value)}/></label><label>Category<input value={form.category} onChange={e=>patch("category",e.target.value)}/></label><label>Duration (minutes)<input required type="number" min="1" max="1440" value={form.durationMinutes} onChange={e=>patch("durationMinutes",e.target.value)}/></label><label>Total marks<input required type="number" min="0.5" step="0.5" value={form.totalMarks} onChange={e=>patch("totalMarks",e.target.value)}/></label><label>Maximum attempts<input type="number" min="1" max="10" value={form.maxAttempts} onChange={e=>patch("maxAttempts",e.target.value)}/></label><label>Starts at<input required type="datetime-local" value={form.startsAt} onChange={e=>patch("startsAt",e.target.value)}/></label><label>Ends at<input required type="datetime-local" value={form.endsAt} onChange={e=>patch("endsAt",e.target.value)}/></label></div>
    <label>Description<textarea rows="3" value={form.description} onChange={e=>patch("description",e.target.value)}/></label><label>Student instructions<textarea rows="4" value={form.instructions} onChange={e=>patch("instructions",e.target.value)}/></label>
    <h3>Eligibility and question configuration</h3><p className="lect-help">Students shown here are those already associated with your exams. To establish additional student-module relationships, an administrator must provide that relationship in the existing data model.</p>
    <label>Eligible students<select multiple value={form.eligibleStudents} onChange={e=>patch("eligibleStudents",Array.from(e.target.selectedOptions,o=>o.value))}>{students.map(s=><option key={s._id} value={s._id}>{s.name} · {s.studentId || s.email}</option>)}</select></label>
    <h3>Question Bank Questions</h3><div className="lect-toolbar"><label className="lect-search"><Search size={16}/><input placeholder="Search questions" value={query} onChange={e=>setQuery(e.target.value)}/></label><select value={moduleFilter} onChange={e=>setModuleFilter(e.target.value)}><option value="">All modules</option>{[...new Set(questions.map(q=>q.module))].map(m=><option key={m}>{m}</option>)}</select><select value={type} onChange={e=>setType(e.target.value)}><option value="">All types</option>{["mcq","true_false","short_answer","essay","bar_chart"].map(t=><option key={t} value={t}>{questionTypeLabel(t)}</option>)}</select><select value={difficulty} onChange={e=>setDifficulty(e.target.value)}><option value="">All difficulties</option>{["easy","medium","hard"].map(t=><option key={t}>{t}</option>)}</select></div>
    <div className="lect-question-list">{questions.filter(q=>(!query||q.text.toLowerCase().includes(query.toLowerCase()))&&(!moduleFilter||q.module===moduleFilter)&&(!type||q.type===type)&&(!difficulty||q.difficulty===difficulty)).map(q=><article key={q._id}><input type="checkbox" checked={form.questions.includes(String(q._id))} onChange={()=>toggle(String(q._id))}/><div><Status value={q.type}/><b>{q.text}</b><small>{q.module} · {readable(q.difficulty)} · {q.marks} marks</small></div></article>)}</div>
    <h3>Selected questions · {selected.length}</h3>{selected.map(q=><div className="lect-option" key={q._id}><span>{q.text} <small>{readable(q.type)}</small></span><label>Marks<input aria-label={`Marks for ${q.text}`} type="number" min="0.5" step="0.5" value={form.questionMarkAllocations?.[String(q._id)]??q.marks} onChange={e=>setQuestionMarks(String(q._id),e.target.value)}/></label><button type="button" className="lect-text-button" onClick={()=>toggle(String(q._id))}>Remove</button></div>)}<p className="lect-help">Selected marks total: {selected.reduce((s,q)=>s+Number(form.questionMarkAllocations?.[String(q._id)]??q.marks),0)}</p>
    <div className="lect-checks"><label><input type="checkbox" checked={form.randomizeQuestions} onChange={e=>patch("randomizeQuestions",e.target.checked)}/> Randomize question order</label><label><input type="checkbox" checked={form.autoSubmit} onChange={e=>patch("autoSubmit",e.target.checked)}/> Auto-submit when time expires</label></div><p className="lect-help">Publishing requires at least one valid question, question marks equal to total marks, an eligible student group, and a future end time.</p>
    <div className="lect-form-actions"><button type="button" className="lect-secondary" onClick={cancel} disabled={saving}>Cancel</button><button type="button" className="lect-secondary" onClick={()=>window.alert(`${form.title || "Untitled exam"}\n${form.module || "No module"}\n${form.questions.length} selected question(s), ${form.totalMarks || 0} total marks`)}>Preview</button><button className="lect-secondary" type="submit" disabled={saving}>{saving?"Saving…":"Save draft"}</button><button type="button" className="lect-primary" disabled={saving} onClick={()=>saveExam(true)}>{saving?"Saving…":"Save & publish"}</button></div>
  </form></Panel>;
}

function Questions({ data, form, setForm, save, editingId, setEditingId, search, setSearch, filter, setFilter, act }) {
  const patch=(k,v)=>setForm(o=>({...o,[k]:v})); const [moduleFilter,setModuleFilter]=useState(""); const [difficultyFilter,setDifficultyFilter]=useState(""); const optionInputs=useRef({}); const markingPointInputs=useRef({}); const rows=(data?.items||[]).filter(q=>(!moduleFilter||q.module===moduleFilter)&&(!difficultyFilter||q.difficulty===difficultyFilter));
  const nextOptionKey=()=>{for(let index=0;index<26;index+=1){const key=String.fromCharCode(65+index);if(!form.options.some(option=>option.key===key))return key;}let suffix=form.options.length+1;while(form.options.some(option=>option.key===`Option ${suffix}`))suffix+=1;return `Option ${suffix}`;};
  const addOption=()=>{const key=nextOptionKey();patch("options",[...form.options,{key,text:""}]);window.requestAnimationFrame(()=>optionInputs.current[key]?.focus());};
  const addMarkingPoint=()=>{const index=form.markingPoints.length;patch("markingPoints",[...form.markingPoints,{description:"",expectedConcept:"",keywords:[],marks:1,explanation:""}]);window.requestAnimationFrame(()=>markingPointInputs.current[index]?.focus());};
  return <div className="lect-columns"><Panel title={editingId?"Edit question":"Add a question"}><form className="lect-form" onSubmit={save}><label>Question text<textarea required rows="4" value={form.text} onChange={e=>patch("text",e.target.value)}/></label><div className="lect-form-grid"><label>Question type<select value={form.type} onChange={e=>patch("type",e.target.value)}><option value="mcq">Multiple choice</option><option value="true_false">True / False</option><option value="short_answer">Short answer</option><option value="essay">Essay / structured</option><option value="bar_chart">Bar Chart Question</option></select></label><label>Module<input required value={form.module} onChange={e=>patch("module",e.target.value)}/></label><label>Topic<input value={form.topic} onChange={e=>patch("topic",e.target.value)}/></label><label>Difficulty<select value={form.difficulty} onChange={e=>patch("difficulty",e.target.value)}><option>easy</option><option>medium</option><option>hard</option></select></label><label>Marks<input required type="number" min="0.5" step="0.5" value={form.marks} onChange={e=>patch("marks",e.target.value)}/></label></div>
    {form.type === "mcq" && <section className="lect-question-editor-section"><div className="lect-editor-section-heading"><div><h3>Answer options</h3><p>Choose exactly one correct answer.</p></div><span className="lect-editor-count">{form.options.length} option{form.options.length===1?"":"s"}</span></div><div className="lect-editor-list">{form.options.map((o,i)=><div className="lect-editor-item lect-option-editor" key={o.key}><span className="lect-option-key">{o.key}</span><label className="lect-editor-field">Option text<input ref={element=>{optionInputs.current[o.key]=element;}} required value={o.text} placeholder={`Enter option ${o.key}`} onChange={e=>patch("options",form.options.map((x,j)=>j===i?{...x,text:e.target.value}:x))}/></label><label className={`lect-correct-control ${form.correctAnswer===o.key?"selected":""}`} title={`Set option ${o.key} as the correct answer`}><input aria-label={`Mark option ${o.key} as correct`} type="radio" name="correctAnswer" checked={form.correctAnswer===o.key} onChange={()=>patch("correctAnswer",o.key)}/><span>Correct</span></label><button type="button" className="lect-icon-danger" title="Remove option" aria-label={`Remove option ${o.key}`} disabled={form.options.length<=2} onClick={()=>{const next=form.options.filter((_,j)=>j!==i);patch("options",next);if(form.correctAnswer===o.key)patch("correctAnswer",next[0].key);}}><Trash2 size={15}/></button></div>)}</div><button className="lect-inline-add-button" type="button" onClick={addOption}><Plus size={15}/> Add Option</button><p className="lect-help">At least two options are required. The selected correct answer is stored for marking.</p></section>}
    {form.type === "true_false" && <label>Correct answer<select value={form.correctAnswer} onChange={e=>patch("correctAnswer",e.target.value)}><option value="true">True</option><option value="false">False</option></select></label>}
    {form.type === "short_answer" && <><label>Model answer<textarea rows="2" value={form.expectedAnswer||""} onChange={e=>patch("expectedAnswer",e.target.value)}/></label><section className="lect-question-editor-section"><div className="lect-editor-section-heading"><div><h3>Marking points</h3><p>Allocate marks across the expected concepts.</p></div><span className={`lect-editor-count ${Math.abs(form.markingPoints.reduce((s,p)=>s+Number(p.marks||0),0)-Number(form.marks||0))<0.001?"balanced":"unbalanced"}`}>{form.markingPoints.reduce((s,p)=>s+Number(p.marks||0),0)} / {form.marks} marks</span></div><div className="lect-editor-list">{form.markingPoints.map((p,i)=><div className="lect-editor-item lect-marking-point-editor" key={i}><div className="lect-marking-point-heading"><span className="lect-editor-index">Point {i+1}</span><button type="button" className="lect-icon-danger" title="Remove marking point" aria-label={`Remove marking point ${i+1}`} disabled={form.markingPoints.length<=1} onClick={()=>patch("markingPoints",form.markingPoints.filter((_,j)=>j!==i))}><Trash2 size={15}/></button></div><div className="lect-marking-point-fields"><label className="lect-editor-field lect-point-description">Point description<input ref={element=>{markingPointInputs.current[i]=element;}} required value={p.description} placeholder="Expected concept or marking point" onChange={e=>patch("markingPoints",form.markingPoints.map((x,j)=>j===i?{...x,description:e.target.value}:x))}/></label><label className="lect-editor-field">Expected concept<input value={p.expectedConcept||""} onChange={e=>patch("markingPoints",form.markingPoints.map((x,j)=>j===i?{...x,expectedConcept:e.target.value}:x))}/></label><label className="lect-editor-field">Keywords<input value={(p.keywords||[]).join(", ")} placeholder="Comma-separated keywords" onChange={e=>patch("markingPoints",form.markingPoints.map((x,j)=>j===i?{...x,keywords:e.target.value.split(",").map(k=>k.trim()).filter(Boolean)}:x))}/></label><label className="lect-editor-field lect-point-marks">Marks<input type="number" min="0.5" step="0.5" value={p.marks} onChange={e=>patch("markingPoints",form.markingPoints.map((x,j)=>j===i?{...x,marks:e.target.value}:x))}/></label><label className="lect-editor-field lect-point-explanation">Marking explanation<textarea rows="2" value={p.explanation||""} onChange={e=>patch("markingPoints",form.markingPoints.map((x,j)=>j===i?{...x,explanation:e.target.value}:x))}/></label></div></div>)}</div><button type="button" className="lect-inline-add-button" onClick={addMarkingPoint}><Plus size={15}/> Add Marking Point</button><p className="lect-help">At least one marking point is required, and point marks must equal the question total.</p></section></>}
    {form.type === "essay" && <><label>Model answer<textarea rows="3" value={form.modelAnswer||""} onChange={e=>patch("modelAnswer",e.target.value)}/></label><section className="lect-question-editor-section"><div className="lect-editor-section-heading"><div><h3>Rubric criteria</h3><p>Allocate marks across the expected concepts.</p></div><span className={`lect-editor-count ${Math.abs(form.rubric.reduce((sum,item)=>sum+Number(item.marks||0),0)-Number(form.marks||0))<0.001?"balanced":"unbalanced"}`}>{form.rubric.reduce((sum,item)=>sum+Number(item.marks||0),0)} / {form.marks} marks</span></div><div className="lect-editor-list">{form.rubric.map((p,i)=><div className="lect-editor-item lect-marking-point-editor lect-rubric-criterion" key={p._id || p._uiKey}><div className="lect-marking-point-heading"><span className="lect-editor-index">Criterion {i+1}</span><button type="button" className="lect-icon-danger" title={`Remove rubric criterion ${i+1}`} aria-label={`Remove rubric criterion ${i+1}`} disabled={form.rubric.length<=1} onClick={()=>patch("rubric",form.rubric.filter((criterion,j)=>j!==i))}><Trash2 size={15}/></button></div><div className="lect-marking-point-fields"><label className="lect-editor-field lect-point-description">Criterion<input required value={p.description} placeholder="Criterion or marking point" onChange={e=>patch("rubric",form.rubric.map((item,j)=>j===i?{...item,description:e.target.value}:item))}/></label><label className="lect-editor-field">Expected concept<textarea rows="2" value={p.expectedConcept||""} onChange={e=>patch("rubric",form.rubric.map((item,j)=>j===i?{...item,expectedConcept:e.target.value}:item))}/></label><label className="lect-editor-field lect-point-marks">Marks<input type="number" min="0.5" step="0.5" value={p.marks} onChange={e=>patch("rubric",form.rubric.map((item,j)=>j===i?{...item,marks:e.target.value}:item))}/></label><label className="lect-editor-field lect-point-explanation">Explanation<textarea rows="2" value={p.explanation||""} onChange={e=>patch("rubric",form.rubric.map((item,j)=>j===i?{...item,explanation:e.target.value}:item))}/></label></div></div>)}</div><button type="button" className="lect-inline-add-button" onClick={()=>patch("rubric",[...form.rubric,{_uiKey:globalThis.crypto?.randomUUID?.() || `rubric-${Date.now()}-${Math.random()}`,description:"",expectedConcept:"",keywords:[],marks:1,explanation:""}])}><Plus size={15}/> Add Rubric Criterion</button><p className="lect-help">At least one rubric criterion is required, and criterion marks must equal the question total.</p></section></>}
    {form.type === "bar_chart" && <><BarChartDataEditor rows={form.chartData || []} onChange={(rows) => patch("chartData", rows)} allowNegative={form.allowNegative} /><div className="lect-checks bar-negative-toggle"><label><input type="checkbox" checked={Boolean(form.allowNegative)} onChange={(event) => patch("allowNegative", event.target.checked)}/> Allow negative values</label></div><p className="lect-help">Enter 1–20 unique reference categories with valid values. A provisional reference-based mark is suggested for lecturer review.</p><details className="lect-bar-preview"><summary>Preview student experience</summary><p>{form.text || "Your question instructions will appear here."}</p><BarChartDataEditor student readOnly rows={[]} onChange={() => {}} allowNegative={form.allowNegative}/></details></>}
    <label>Lecturer explanation<textarea rows="2" value={form.explanation} onChange={e=>patch("explanation",e.target.value)}/></label><div className="lect-form-actions"><button className="lect-secondary" type="button" onClick={()=>{setEditingId("");setForm({text:"",type:"mcq",module:"",topic:"",difficulty:"medium",marks:1,options:[{key:"A",text:""},{key:"B",text:""}],correctAnswer:"A",expectedAnswer:"",markingPoints:[],modelAnswer:"",rubric:[],chartData:[],allowNegative:false,markingGuide:"",explanation:""});}}>Reset</button><button className="lect-primary" type="submit">{editingId?"Update question":"Save question"}</button></div></form></Panel>
    <Panel title="Reusable questions"><div className="lect-toolbar"><label className="lect-search"><Search size={16}/><input placeholder="Search questions" value={search} onChange={e=>setSearch(e.target.value)}/></label><select aria-label="Filter by question type" value={filter} onChange={e=>setFilter(e.target.value)}><option value="">All types</option>{["mcq","true_false","short_answer","essay","bar_chart"].map(t=><option key={t} value={t}>{questionTypeLabel(t)}</option>)}</select><select aria-label="Filter by module" value={moduleFilter} onChange={e=>setModuleFilter(e.target.value)}><option value="">All modules</option>{[...new Set((data?.items||[]).map(q=>q.module))].map(m=><option key={m}>{m}</option>)}</select><select aria-label="Filter by difficulty" value={difficultyFilter} onChange={e=>setDifficultyFilter(e.target.value)}><option value="">All difficulties</option>{["easy","medium","hard"].map(x=><option key={x}>{readable(x)}</option>)}</select></div><div className="lect-question-list">{rows.length?rows.map(q=><article className="lect-question-card" key={q._id}><div className="lect-question-card-content"><div className="lect-question-card-header"><span className={`lect-question-type ${q.type}`}>{questionTypeLabel(q.type)}</span><span className="lect-question-marks">{q.marks} Marks</span></div><h3 title={q.text}>{q.text || "Question text unavailable"}</h3><div className="lect-question-meta"><span>{q.module || "Module unavailable"}</span>{q.topic&&<span>{q.topic}</span>}<span>{readable(q.difficulty)}</span><span>{dateOnly(q.createdAt)}</span></div><details className="lect-question-details"><summary>View full question and answer details</summary><p className="lect-question-full">{q.text || "Question text unavailable"}</p><p>{q.type==="mcq"?q.options?.map(o=>`${o.key}. ${o.text}`).join(" · "):q.type==="short_answer"?`Expected: ${q.expectedAnswer||"—"} · ${(q.markingPoints||[]).map(p=>`${p.description} (${p.marks})`).join("; ")}`:q.type==="essay"?`Model answer: ${q.modelAnswer||"—"} · ${(q.rubric||[]).map(p=>`${p.description} (${p.marks})`).join("; ")}`:q.type==="bar_chart"?`Reference bars: ${(q.chartData||[]).map(bar=>`${bar.category}: ${bar.value}`).join(" · ")}`:`Correct answer: ${q.correctAnswer}`}</p></details></div><div className="lect-question-card-actions"><button className="lect-icon-action" type="button" title="Edit question" aria-label="Edit question" onClick={()=>{setEditingId(q._id);setForm({text:q.text,type:q.type,module:q.module,topic:q.topic||"",difficulty:q.difficulty,marks:q.marks,options:q.options?.length?q.options:[{key:"A",text:""},{key:"B",text:""}],correctAnswer:q.correctAnswer||"A",expectedAnswer:q.expectedAnswer||"",markingPoints:q.markingPoints||[],modelAnswer:q.modelAnswer||"",rubric:q.rubric||[],chartData:q.chartData||[],allowNegative:Boolean(q.allowNegative),markingGuide:q.markingGuide||"",explanation:q.explanation||""});}}><Pencil size={15}/></button><button className="lect-icon-action" type="button" title="Duplicate question" aria-label="Duplicate question" onClick={()=>{const copy=Object.fromEntries(Object.entries(q).filter(([key])=>!['_id','lecturer','createdAt','updatedAt','__v'].includes(key)));act(()=>lecturerRequest("/questions",sendJson("POST",{...copy,text:`${q.text} (Copy)`})),"Question duplicated.");}}><Plus size={15}/></button><button className="lect-icon-danger" type="button" title="Delete question" aria-label="Delete question" onClick={()=>window.confirm("Delete this question from the bank?")&&act(()=>lecturerRequest(`/questions/${q._id}`,{method:"DELETE"}),"Question deleted.")}><Trash2 size={15}/></button></div></article>):<Empty>No questions match. Add the first one here.</Empty>}</div></Panel></div>;
}

function Schedule({ data, navigate }) { const items=data?.items||[]; const grouped=items.reduce((a,e)=>{const key=dateOnly(e.startsAt);(a[key] ||= []).push(e);return a;},{}); return <div className="lect-schedule">{Object.keys(grouped).length?Object.entries(grouped).map(([day,rows])=><Panel title={day} key={day}><Table rows={rows} columns={[{label:"Exam",render:r=><>{r.title}{r.conflictsWith?.length>0&&<small className="lect-warning">Schedule conflict with {r.conflictsWith.map(x=>x.title).join(", ")}</small>}</>},{label:"Module",key:"module"},{label:"Time",render:r=>date(r.startsAt)},{label:"End",render:r=>date(r.endsAt)},{label:"Status",render:r=><Status value={r.status}/>},{label:"Action",render:r=>r.status==="draft"?<button className="lect-text-button" onClick={()=>navigate(`/lecturer/exams/create?edit=${r._id}`)}>Edit draft</button>:"—"}]}/></Panel>):<Panel title="Exam calendar"><Empty>No scheduled exams yet.</Empty></Panel>}</div>; }
function Attempts({ data, navigate }) { return <Panel title="Exam attempts"><Table rows={data?.items} columns={[{label:"Student",render:r=><>{r.student?.name}<small className="lect-sub">{r.student?.studentId || r.student?.email}</small></>},{label:"Exam",render:r=><>{r.exam?.title}<small className="lect-sub">{r.exam?.module}</small></>},{label:"Attempt",render:r=>r.attemptNumber || 1},{label:"Started",render:r=>date(r.startedAt)},{label:"Submitted",render:r=>date(r.submittedAt)},{label:"Status",render:r=><Status value={r.status}/>},{label:"Evaluation",render:r=><Status value={r.evaluationStatus}/>},{label:"Details",render:r=><button type="button" className="lect-attempt-view" onClick={()=>navigate(`/lecturer/submissions?submission=${r._id}`)}><Eye size={14}/> View Details</button>}]}/></Panel>; }
function Submissions({ data, selected, navigate, location, act, evaluation }) {
  const [draft, setDraft] = useState({ submissionId: "", answers: {} });
  const [saving, setSaving] = useState(false);
  if (!selected) return <Panel title={evaluation ? "Choose a submission to evaluate" : "Submitted exam work"}><Table rows={data?.items} columns={[{ label: "Student", render: (r) => <>{r.student?.name}<small className="lect-sub">{r.student?.studentId || ""}</small></> }, { label: "Exam", render: (r) => <>{r.exam?.title}<small className="lect-sub">{r.exam?.module}</small></> }, { label: "Submitted", render: (r) => date(r.submittedAt) }, { label: "Progress", render: (r) => <Status value={r.evaluationStatus} /> }, { label: "Action", render: (r) => <button className="lect-primary small" onClick={() => navigate(`/lecturer/${evaluation ? "evaluation" : "submissions"}?submission=${r._id}`)}>{evaluation ? "Evaluate" : "View submission"}</button> }]} /></Panel>;
  const freshDraft = Object.fromEntries((selected.answers || []).map((answer) => {
    const q = answer.question || {};
    const id = String(q._id || answer.question);
    const criteria = q.type === "essay" ? q.rubric || [] : q.type === "short_answer" ? q.markingPoints || [] : [];
    return [id, { criteria: criteria.map((criterion, index) => ({ marksAwarded: answer.criterionScores?.[index]?.marksAwarded ?? answer.markingFeedback?.[index]?.marksAwarded ?? 0, feedback: answer.criterionScores?.[index]?.feedback || "" })), manualOverrideEnabled: answer.manualOverrideMarks !== null && answer.manualOverrideMarks !== undefined, manualOverrideMarks: answer.manualOverrideMarks ?? "", feedback: answer.feedback || "", reviewed: Boolean(answer.reviewed) }];
  }));
  const grades = draft.submissionId === selected._id ? draft.answers : freshDraft;
  const updateGrade = (id, values) => setDraft({ submissionId: selected._id, answers: { ...grades, [id]: { ...grades[id], ...values } } });
  const scoreFor = (answer, question, grade) => {
    const criteria = question.type === "essay" ? question.rubric || [] : question.type === "short_answer" ? question.markingPoints || [] : [];
    const rubricTotal = criteria.reduce((sum, criterion, index) => sum + Number(grade.criteria?.[index]?.marksAwarded || 0), 0);
    const automatic = answer.automaticMarks === null || answer.automaticMarks === undefined || answer.automaticMarks === "" ? NaN : Number(answer.automaticMarks);
    const final = grade.manualOverrideEnabled ? Number(grade.manualOverrideMarks) : criteria.length ? rubricTotal : automatic;
    return { criteria, rubricTotal, automatic, final };
  };
  const rows = (selected.answers || []).map((answer) => {
    const q = answer.question || {};
    const id = String(q._id || answer.question);
    const grade = grades[id] || { criteria: [], manualOverrideEnabled: false, manualOverrideMarks: "", feedback: "", reviewed: false };
    return { answer, q, id, grade, ...scoreFor(answer, q, grade) };
  });
  const allMarksValid = rows.every((row) => row.criteria.every((criterion, criterionIndex) => {
    const value = Number(row.grade.criteria?.[criterionIndex]?.marksAwarded);
    return row.grade.criteria?.[criterionIndex]?.marksAwarded !== "" && Number.isFinite(value) && value >= 0 && value <= Number(criterion.marks);
  }) && (!row.grade.manualOverrideEnabled || (row.grade.manualOverrideMarks !== "" && Number(row.grade.manualOverrideMarks) >= 0 && Number(row.grade.manualOverrideMarks) <= Number(row.q.marks))) && Number.isFinite(row.final) && row.final >= 0 && row.final <= Number(row.q.marks));
  const canFinalize = rows.length > 0 && allMarksValid && rows.every((row) => row.grade.reviewed);
  const saveEvaluation = async (finalize) => {
    setSaving(true);
    try {
      const answers = rows.map(({ id, grade, criteria }) => ({
        questionId: id,
        criterionScores: criteria.map((criterion, index) => ({ marksAwarded: Number(grade.criteria?.[index]?.marksAwarded ?? 0), feedback: grade.criteria?.[index]?.feedback || "" })),
        manualOverrideMarks: grade.manualOverrideEnabled ? Number(grade.manualOverrideMarks) : null,
        feedback: grade.feedback || "",
        reviewed: grade.reviewed,
      }));
      await act(() => lecturerRequest(`/submissions/${selected._id}/evaluate`, sendJson("PATCH", { answers, finalize })), finalize ? "Evaluation finalized and result total saved." : "Evaluation draft saved.");
    } finally { setSaving(false); }
  };
  const backParams = new URLSearchParams(location.search); backParams.delete("submission");
  const backToList = () => navigate(`/lecturer/${evaluation ? "evaluation" : "submissions"}${backParams.size ? `?${backParams}` : ""}`);
  return <Panel title={`${evaluation ? "Answer evaluation" : "Submission detail"} · ${selected.student?.name || "Student"}`} action={<button className="lect-secondary lect-back-button" onClick={backToList}><ArrowLeft size={16}/> Back to list</button>}>
    <div className="lect-submission-meta"><b>{selected.exam?.title}</b><span>{selected.exam?.module}</span><span>{selected.student?.studentId || selected.student?.email}</span><span>{selected.student?.email}</span><span>Submitted {date(selected.submittedAt)}</span><Status value={selected.evaluationStatus}/>{selected.evaluationFinalizedAt && <span>Finalized {date(selected.evaluationFinalizedAt)}</span>}</div>
    {((selected.browserActivity || []).length > 0 || (selected.flaggedQuestions || []).length > 0) && <section className="lect-rubric-review"><b>Exam activity and flags</b><p>Browser events and question flags are review signals only. They do not prove misconduct or affect marks or attempt status.</p>{(selected.flaggedQuestions || []).length > 0 && <p>Flagged questions: {(selected.flaggedQuestions || []).map((id) => { const position = selected.answers.findIndex((answer) => String(answer.question) === String(id)); return position >= 0 ? `Q${position + 1}` : null; }).filter(Boolean).join(", ")}</p>}{(selected.browserActivity || []).length > 0 && <ul>{selected.browserActivity.map((event, eventIndex) => <li key={event._id || event.dedupeKey || eventIndex}>{String(event.type).replaceAll("_", " ")} · {date(event.occurredAt)}</li>)}</ul>}</section>}
    <div className="lect-answers">{rows.map(({ answer, q, id, grade, criteria, rubricTotal, automatic, final }, index) => <article key={id || index}>
      <div className="lect-answer-question"><small>Question {index + 1} · {readable(q.type)} · Maximum {q.marks ?? "—"}</small><h3>{q.text || "Question details unavailable"}</h3></div>
      <div className="lect-student-answer"><b>Student response</b><p>{q.type === "bar_chart" ? (Array.isArray(answer.response) && answer.response.length ? `${answer.response.length} bar entries submitted.` : "No answer provided") : answer.response === null || answer.response === undefined || answer.response === "" ? "No answer provided" : typeof answer.response === "string" ? answer.response : JSON.stringify(answer.response)}</p></div>{q.type === "bar_chart" && <section className="lect-bar-submission"><div><b>Submitted bar data</b>{Array.isArray(answer.response) && answer.response.length ? <div className="lect-bar-answer-table"><span><strong>Category</strong><strong>Value</strong></span>{answer.response.map((bar, barIndex) => <span key={`${bar.category}-${barIndex}`}><b>{bar.category || "—"}</b><i>{bar.value === "" ? "—" : bar.value}</i></span>)}</div> : <p>No bar chart data was submitted.</p>}</div><div><b>Student chart</b><BarChart rows={answer.response || []} allowNegative={q.allowNegative} title={`Student answer for question ${index + 1}`}/></div></section>}{(q.modelAnswer || q.expectedAnswer) && <div className="lect-model-answer"><b>{q.modelAnswer ? "Model answer" : "Expected answer"}</b><p>{q.modelAnswer || q.expectedAnswer}</p></div>}
      {evaluation && <>
        {["mcq", "true_false"].includes(q.type) && <div className="lect-rubric-review"><p><b>Student answer:</b> {answer.response === null || answer.response === undefined || answer.response === "" ? "Unanswered" : q.type === "mcq" ? (q.options || []).find((option) => option.key === answer.response)?.text || answer.response : String(answer.response)}</p><p><b>Correct answer:</b> {q.type === "mcq" ? `${q.correctAnswer} · ${(q.options || []).find((option) => option.key === q.correctAnswer)?.text || ""}` : String(q.correctAnswer ?? "Unavailable")}</p></div>}
        {criteria.length > 0 && <section className="lect-rubric-panel" aria-label={`${readable(q.type)} marking rubric`}><div className="lect-rubric-heading"><div><span className="lect-rubric-eyebrow">MARKING RUBRIC</span><h4>Criterion review</h4><p>Automatic values are provisional suggestions. Review each criterion before finalizing.</p></div><div className="lect-rubric-summary"><div><span>Automatic suggestion</span><b>{automatic} / {q.marks}</b></div><div><span>Lecturer rubric total</span><b>{rubricTotal} / {q.marks}</b></div><div><span>Maximum marks</span><b>{q.marks}</b></div></div></div><div className="lect-criterion-grid">{criteria.map((criterion, criterionIndex) => {
          const score = grade.criteria?.[criterionIndex] || { marksAwarded: 0, feedback: "" };
          const suggestion = answer.criterionScores?.[criterionIndex] || {};
          const changeCriterion = (values) => updateGrade(id, { criteria: grade.criteria.map((item, itemIndex) => itemIndex === criterionIndex ? { ...item, ...values } : item) });
          const criterionValue = Number(score.marksAwarded); const criterionInvalid = score.marksAwarded === "" || !Number.isFinite(criterionValue) || criterionValue < 0 || criterionValue > Number(criterion.marks);
          return <article className="lect-criterion-card" key={`${id}-${criterionIndex}`}><header><div><span className="lect-criterion-index">Criterion {criterionIndex + 1}</span><h5>{criterion.title || criterion.description || `Criterion ${criterionIndex + 1}`}</h5></div><span className="lect-criterion-max">Max <b>{criterion.marks}</b></span></header>{criterion.title && criterion.description && <p className="lect-criterion-description">{criterion.description}</p>}{criterion.expectedConcept && <div className="lect-criterion-context"><b>Expected concept</b><p>{criterion.expectedConcept}</p></div>}{criterion.explanation && <div className="lect-criterion-context"><b>Marking guidance</b><p>{criterion.explanation}</p></div>}<div className="lect-suggestion-row"><div><span className="lect-feedback-caption">Automatic suggestion</span><b>{suggestion.automaticMarks ?? suggestion.marksAwarded ?? 0} / {criterion.marks}</b>{suggestion.feedback && <p>{suggestion.feedback}</p>}</div><span className={`lect-review-badge ${suggestion.requiresReview ? "needs-review" : "suggested"}`}>{suggestion.requiresReview ? "Review required" : "Provisional"}</span></div><div className="lect-criterion-controls"><label>Lecturer marks <small>Maximum {criterion.marks}</small><input type="number" min="0" max={criterion.marks} step="0.5" value={score.marksAwarded} aria-invalid={criterionInvalid} onChange={(event) => changeCriterion({ marksAwarded: event.target.value })}/>{criterionInvalid && <small className="lect-field-error" role="alert">Enter a mark from 0 to {criterion.marks}.</small>}</label><label className="lect-feedback-field">Criterion feedback<textarea rows="3" value={score.feedback} onChange={(event) => changeCriterion({ feedback: event.target.value })}/></label></div></article>;
        })}</div></section>}
        <div className="lect-evaluation-summary"><div className="lect-evaluation-scores"><div><span>Automatic suggestion</span><b>{automatic} / {q.marks}</b><small>{answer.markingMethod || "Server-side answer/rubric baseline"}</small>{q.type === "bar_chart" && answer.markingFeedback?.[0]?.rationale && <small>{answer.markingFeedback[0].rationale}</small>}</div>{criteria.length > 0 && <div><span>Current rubric total</span><b>{rubricTotal} / {q.marks}</b></div>}<div className={grade.manualOverrideEnabled ? "override-active" : ""}><span>{grade.manualOverrideEnabled ? "Manual overall override" : "Final question mark"}</span><b>{Number.isFinite(final) ? final : "—"} / {q.marks}</b><small>{grade.manualOverrideEnabled ? "Override is active" : q.type === "bar_chart" ? "Provisional reference comparison; lecturer review required" : "Based on current rubric or automatic mark"}</small></div></div>
          <label className={`lect-override-toggle ${grade.manualOverrideEnabled ? "is-enabled" : ""}`}><input type="checkbox" checked={grade.manualOverrideEnabled} onChange={(event) => updateGrade(id, { manualOverrideEnabled: event.target.checked })}/><span><strong>Override Overall Question Mark</strong><small>Use a lecturer-set mark instead of the automatic or rubric total for this question.</small></span></label>
          {grade.manualOverrideEnabled && <label className="lect-override-field">Manual overall mark <small>Maximum {q.marks}</small><input type="number" min="0" max={q.marks || 0} step="0.5" value={grade.manualOverrideMarks} aria-invalid={grade.manualOverrideMarks === "" || Number(grade.manualOverrideMarks) > Number(q.marks) || Number(grade.manualOverrideMarks) < 0} onChange={(event) => updateGrade(id, { manualOverrideMarks: event.target.value })}/>{(grade.manualOverrideMarks === "" || Number(grade.manualOverrideMarks) > Number(q.marks) || Number(grade.manualOverrideMarks) < 0) && <small className="lect-field-error" role="alert">Enter a mark from 0 to {q.marks}.</small>}</label>}
          <label className="lect-feedback-field">Lecturer feedback<textarea rows="4" value={grade.feedback} onChange={(event) => updateGrade(id, { feedback: event.target.value })}/></label>
          <label className={`lect-override-toggle lect-review-toggle ${grade.reviewed ? "is-enabled" : ""}`}><input type="checkbox" checked={grade.reviewed} onChange={(event) => updateGrade(id, { reviewed: event.target.checked })}/><span><strong>I reviewed this question and its final mark</strong><small>Confirm this question has been checked before finalizing the evaluation.</small></span></label>
          <small>Status: {grade.manualOverrideEnabled ? "Manually adjusted" : answer.markingMethod ? "Automatic / rubric suggestion" : "Requires lecturer review"}{answer.markingFeedback?.some((item) => item.requiresReview) ? " · Review required" : ""}</small>
        </div>
      </>}
    </article>)}</div>
    {evaluation && <><section className={`lect-final-total ${selected.evaluationFinalizedAt ? "is-finalized" : "is-provisional"}`} aria-label={selected.evaluationFinalizedAt ? "Finalized exam total" : "Current provisional total"}><div className="lect-final-total-copy"><span className="lect-final-total-icon">{selected.evaluationFinalizedAt ? <Check size={18}/> : <Activity size={18}/>}</span><div><h3>{selected.evaluationFinalizedAt ? "Finalized Exam Total" : "Current Provisional Total"}</h3><p>{selected.evaluationFinalizedAt ? `Finalized ${date(selected.evaluationFinalizedAt)}` : "Updates as you adjust marks; not finalized yet."}</p></div></div><strong className="lect-final-total-value">{rows.reduce((sum, row) => sum + (Number.isFinite(row.final) ? row.final : 0), 0)} <span>/ {selected.exam?.totalMarks ?? rows.reduce((sum, row) => sum + Number(row.q.marks || 0), 0)} marks</span></strong><div className="lect-final-total-meta"><Status value={selected.evaluationStatus}/><span>{rows.length} questions</span></div></section><div className="lect-form-actions"><button type="button" className="lect-secondary" disabled={saving || !allMarksValid} onClick={() => saveEvaluation(false)}>{saving ? "Saving…" : "Save evaluation"}</button><button type="button" className="lect-primary" disabled={saving || !canFinalize || Boolean(selected.evaluationFinalizedAt)} onClick={() => saveEvaluation(true)}>{saving ? "Saving…" : "Finalize evaluation"}</button></div>{!allMarksValid && <p className="lect-field-error" role="alert">Check the highlighted marks. Criterion and overall marks must be within their allowed ranges before saving.</p>}<p className="lect-help">Finalization locks marks after results are published. Unpublished finalized evaluations can be reopened and edited with an audit trail.</p></>}
  </Panel>;
}
function Results({ data, act }) { const rows=data?.items||[]; const exams=[...new Map(rows.filter(r=>r.exam).map(r=>[r.exam._id,r.exam])).values()]; const exportCsv=()=>{const quote=v=>`"${String(v??"").replaceAll('"','""')}"`;const csv=[["Exam","Module","Student","Student ID","Marks","Maximum marks","Percentage","Grade","Published"],...rows.map(r=>[r.exam?.title,r.exam?.module,r.student?.name,r.student?.studentId,r.marksObtained,r.maximumMarks,r.maximumMarks?(r.marksObtained/r.maximumMarks*100).toFixed(1):"",r.grade||"",r.isPublished?"Yes":"No"])].map(row=>row.map(quote).join(",")).join("\r\n");const url=URL.createObjectURL(new Blob([csv],{type:"text/csv;charset=utf-8"}));const a=document.createElement("a");a.href=url;a.download="examora-results.csv";a.click();URL.revokeObjectURL(url);}; return <><Panel title="Results and grades" action={<div className="lect-form-actions compact-actions"><span className="lect-help">{data?.note}</span><button className="lect-secondary" onClick={exportCsv}>Export CSV</button><button className="lect-secondary" onClick={()=>window.print()}>Print</button></div>}><Table rows={rows} columns={[{label:"Exam",render:r=><>{r.exam?.title}<small className="lect-sub">{r.exam?.module}</small></>},{label:"Student",render:r=><>{r.student?.name}<small className="lect-sub">{r.student?.studentId||""}</small></>},{label:"Marks",render:r=>`${r.marksObtained} / ${r.maximumMarks}`},{label:"Percentage",render:r=>r.maximumMarks?`${(r.marksObtained/r.maximumMarks*100).toFixed(1)}%`:"—"},{label:"Grade",render:r=>r.grade||"Not configured"},{label:"Evaluation",render:r=><Status value={r.attempt?.evaluationStatus}/>},{label:"Publication",render:r=><Status value={r.isPublished?"published":"draft"}/>}]} empty="No completed evaluations to show."/></Panel>{exams.filter(e=>!e.resultPublished).map(e=><div className="lect-publish-row" key={e._id}><span><b>{e.title}</b><small>{e.module} · publish only after all submitted attempts are evaluated</small></span><button className="lect-primary small" onClick={()=>act(()=>lecturerRequest(`/exams/${e._id}/publish-results`,sendJson("POST",{})),"Official results published.")}>Publish results</button></div>)}</>; }
function Analytics({ data, search, setSearch, page, setPage, sort, setSort }) {
  const [studentId, setStudentId] = useState(""); const [detailState, setDetail] = useState(null); const [detailError, setDetailError] = useState(null);
  useEffect(() => { if (!studentId) return undefined; let active = true; lecturerRequest(`/analytics/students/${studentId}`).then((result) => { if (active) setDetail({ id: studentId, result }); }).catch((error) => { if (active) setDetailError({ id: studentId, message: error.message || "Unable to load student details." }); }); return () => { active = false; }; }, [studentId]);
  const summary = data?.summary || {}; const exams = data?.byExam || []; const students = data?.items || [];
  const detail = detailState?.id === studentId ? detailState.result : null;
  if (studentId) return <div className="lect-analytics-detail"><button className="lect-secondary lect-back-button" onClick={() => setStudentId("")}><ArrowLeft size={16}/> Back to rankings</button>{detailError?.id === studentId ? <div className="lect-error" role="alert">{detailError.message}<button onClick={() => setStudentId("")}>Back to rankings</button></div> : !detail ? <div className="lect-skeleton" role="status"><i/><i/><i/></div> : <>
    <Panel title={detail.student.name} action={<span className="lect-analytics-student-meta">{detail.student.studentId || detail.student.email} · {detail.student.programme || "Programme not provided"}</span>}><p className="lect-help">Only valid finalized, published results from exams this lecturer manages contribute. The weighted average is total marks obtained divided by total maximum marks.</p><div className="lect-stat-grid compact">{[["Released results",detail.summary.publishedResults],["Weighted average",detail.summary.averagePercentage == null ? "—" : `${detail.summary.averagePercentage.toFixed(1)}%`],["Highest exam score",detail.summary.highestPercentage == null ? "—" : `${detail.summary.highestPercentage.toFixed(1)}%`],["Pending evaluations",detail.summary.pendingEvaluations]].map(([key,value])=><article className="lect-stat" key={key}><span>{key}</span><strong>{value}</strong></article>)}</div></Panel>
    <Panel title="Assessment progress"><ProgressLineChart points={detail.history.map((row,index)=>({id:row.examId,label:row.exam,percentage:row.percentage,marksObtained:row.marksObtained,maximumMarks:row.maximumMarks,date:dateOnly(row.publishedAt),index}))} color="#5c65d8"/><Table rows={detail.history} columns={[{label:"Exam",render:r=><>{r.exam}<small className="lect-sub">{r.module}</small></>},{label:"Exam date",render:r=>dateOnly(r.examDate)},{label:"Submitted",render:r=>date(r.submissionDate)},{label:"Score",render:r=>`${r.marksObtained}/${r.maximumMarks}`},{label:"Percentage",render:r=>`${r.percentage.toFixed(1)}%`}]} empty="No released results for this student."/></Panel>
    <Panel title="Module performance"><div className="lect-chart-bars">{detail.byModule.map((row)=><div key={row.module}><span>{row.module}</span><div><i style={{width:`${Math.max(2,Math.min(100,row.averagePercentage))}%`}}/></div><b>{row.averagePercentage.toFixed(1)}%</b><small>{row.resultCount} released result{row.resultCount===1?"":"s"}</small></div>)}</div>{!detail.byModule.length&&<Empty>No module results are available.</Empty>}</Panel>
    {detail.pendingExams.length>0&&<Panel title="Awaiting evaluation"><Table rows={detail.pendingExams} columns={[{label:"Exam",key:"title"},{label:"Module",key:"module"},{label:"Status",render:r=><Status value={r.evaluationStatus}/>}]} /></Panel>}
  </>}</div>;
  return <div className="lect-analytics"><Panel title="Class performance overview"><p className="lect-help">Student averages use total finalized marks obtained divided by total maximum marks across eligible published exams. Unreleased, pending, and missing results are excluded. {data?.summary?.insufficientResults ?? 0} eligible students have no published score yet.</p><div className="lect-stat-grid">{[["Eligible students",summary.totalStudents ?? 0],["Published assessments",summary.totalAssessments ?? 0],["Class average",summary.averageClassPercentage == null ? "—" : `${summary.averageClassPercentage.toFixed(1)}%`],["Highest student average",summary.highestPercentage == null ? "—" : `${summary.highestPercentage.toFixed(1)}%`],["Lowest student average",summary.lowestPercentage == null ? "—" : `${summary.lowestPercentage.toFixed(1)}%`],["Awaiting evaluation",summary.pendingEvaluations ?? 0]].map(([key,value])=><article className="lect-stat" key={key}><span>{key}</span><strong>{value}</strong></article>)}</div></Panel>
    <Panel className="lect-top-three-panel" title={<span className="lect-top-three-title"><span className="lect-top-three-icon"><Trophy size={19}/></span><span><b>Top 3 Students</b><small>Outstanding academic performers</small></span></span>}>
      <div className="lect-top-three-meta"><p className="lect-help">Ranked by weighted average across eligible finalized published exams. Equal percentages share the same rank.</p>{data?.topStudents?.length>0&&<span className="lect-leaderboard-accent" aria-hidden="true"/>}</div>
      <div className="lect-podium">{(data?.topStudents||[]).map((student,index)=>{
        const rank = Number.isInteger(student.rank) && student.rank > 0 ? student.rank : index + 1;
        const average = Number(student.averagePercentage); const hasAverage = Number.isFinite(average);
        const scoreLabel = hasAverage ? `${average.toFixed(1)}%` : "—";
        const scoreCaption = "Weighted average score";
        const PlaceIcon = rank === 1 ? Trophy : Medal;
        return <button type="button" key={student.id} className={`lect-podium-card rank-${Math.min(rank,3)} ${["podium-center","podium-left","podium-right"][index]||""}`} onClick={()=>setStudentId(student.id)} aria-label={`View ${student.name || "student"} performance, rank ${rank}`}>
          <span className="lect-podium-card-top"><span className="lect-podium-medal"><PlaceIcon size={19}/><span>{rank === 1 ? "1st place" : rank === 2 ? "2nd place" : rank === 3 ? "3rd place" : `Rank ${rank}`}</span></span>{index===0&&rank===1&&<span className="lect-leading-badge">LEADER</span>}</span>
          <span className="lect-podium-student"><b title={student.name || "Name unavailable"}>{student.name || "Name unavailable"}</b><small>{student.studentId || "Student ID not provided"}</small></span>
          <span className="lect-podium-score"><small>{scoreCaption}</small><strong>{scoreLabel}</strong></span>
          {hasAverage&&<span className="lect-podium-progress" role="img" aria-label={`Average performance ${average.toFixed(1)} percent`}><i style={{width:`${Math.max(0,Math.min(100,average))}%`}}/></span>}
          <small className="lect-podium-results">{student.resultCount} released result{student.resultCount===1?"":"s"}</small>
        </button>;
      })}</div>{!data?.topStudents?.length&&<Empty>Rankings will appear after results are published.</Empty>}
    </Panel>
    <Panel title="Student performance ranking"><div className="lect-toolbar"><label className="lect-search"><Search size={16}/><input placeholder="Search student name or ID" value={search} onChange={event=>setSearch(event.target.value)}/></label><select aria-label="Rank students by" value={sort} onChange={event=>setSort(event.target.value)}><option value="average">Average percentage</option><option value="total">Total marks</option><option value="name">Name</option></select></div><p className="lect-help">{data?.ranking?.description}</p><Table rows={students} columns={[{label:"Rank",render:r=><b>#{r.rank}</b>},{label:"Student",render:r=><><b>{r.name}</b><small className="lect-sub">{r.studentId||"ID not provided"} · {r.programme||"Programme not provided"}</small></>},{label:"Released results",key:"resultCount"},{label:"Average",render:r=>`${r.averagePercentage.toFixed(1)}%`},{label:"Latest result",render:r=>`${r.latestPercentage.toFixed(1)}%`},{label:"Details",render:r=><button className="lect-secondary small" onClick={()=>setStudentId(r.id)}>View performance</button>}]} empty="No released results match this search."/><div className="lect-pagination"><span>{data?.total ? `Showing ${(page-1)*10+1}–${Math.min(page*10,data.total)} of ${data.total}` : "No ranked students"}</span><button className="lect-secondary small" disabled={page<=1} onClick={()=>setPage(page-1)}>Previous</button><span>Page {data?.pages ? page : 0} of {data?.pages||0}</span><button className="lect-secondary small" disabled={!data?.pages||page>=data.pages} onClick={()=>setPage(page+1)}>Next</button></div></Panel>
    <Panel title="Exam performance"><div className="lect-chart-bars">{exams.map(row=><div key={row.id}><span>{row.title}<small className="lect-sub">{row.module} · {dateOnly(row.startsAt)}</small></span><div><i style={{width:`${Math.max(2,Math.min(100,row.averagePercentage||0))}%`}}/></div><b>{row.averagePercentage==null?"No released scores":`${row.averagePercentage.toFixed(1)}% average`}</b><small>{row.resultCount} released results · {row.eligibleStudentCount} eligible students · {row.pendingEvaluations} pending evaluations</small></div>)}</div>{!exams.length&&<Empty>No published exam results available yet.</Empty>}</Panel></div>;
}
function Students({ data, search, setSearch }) { return <Panel title="Associated students"><label className="lect-search"><Search size={16}/><input placeholder="Search name, student ID or email" value={search} onChange={e=>setSearch(e.target.value)}/></label><p className="lect-help">{data?.scope}</p><Table rows={data?.items} columns={[{label:"Student",render:r=><><b>{r.name}</b><small className="lect-sub">{r.studentId||"ID not provided"}</small></>},{label:"Email",key:"email"},{label:"Programme",render:r=>r.programme||"—"},{label:"Eligible exams",key:"examCount"},{label:"Attempts",key:"attempts"}]}/></Panel>; }
function Notifications({ data, act }) {
  const rows = data?.items || [];
  const unreadCount = data?.unreadCount || 0;
  return <Panel title="Notifications" action={<button type="button" className="student-secondary-button" onClick={() => act(() => lecturerRequest("/notifications/read-all", sendJson("PATCH", {})), "Notifications marked as read.")}>Mark all as read</button>}>
    <p className="lect-notification-summary">{unreadCount} unread notification{unreadCount === 1 ? "" : "s"}</p>
    {rows.length ? <section className="student-notification-list lect-notification-list">{rows.map((notification) => <article className={`student-notification ${notification.readAt ? "is-read" : "is-unread"}`} key={notification._id}>
      <span className="notification-indicator" aria-hidden="true"/>
      <div className="lect-notification-content"><div className="notification-title-row"><div className="lect-notification-heading"><h2>{notification.title}</h2></div><time>{date(notification.createdAt)}</time></div><p>{notification.message}</p><span className="notification-kind">{String(notification.type).replaceAll("_", " ")}</span></div>
      {!notification.readAt && <button type="button" className="student-secondary-button lect-notification-read" onClick={() => act(() => lecturerRequest(`/notifications/${notification._id}/read`, sendJson("PATCH", {})), "Notification marked read.")}>Mark read</button>}
    </article>)}</section> : <div className="student-empty-state"><span className="student-empty-icon"><Bell size={20} aria-hidden="true"/></span><h3>No notifications yet</h3><p>New submissions will appear here.</p></div>}
  </Panel>;
}
function Profile({ profile, setProfile, act }) { return <Panel title="Lecturer profile"><form className="lect-form lect-profile-form" onSubmit={e=>{e.preventDefault();act(()=>lecturerRequest("/profile",sendJson("PATCH",profile)),"Profile updated.");}}><div className="lect-form-grid"><label>Full name<input required value={profile.name} onChange={e=>setProfile({...profile,name:e.target.value})}/></label><label>Department<input value={profile.department} onChange={e=>setProfile({...profile,department:e.target.value})}/></label><label>Email<input disabled value={profile.email || "Not provided"}/></label><label>Account role<input disabled value={profile.role || "Lecturer"}/></label><label>Lecturer ID<input disabled value={profile.lecturerId || "Not provided"}/></label></div><p className="lect-help">Email, role, account status and lecturer identifier are read-only. Missing department or lecturer ID values are not fabricated.</p><div className="lect-form-actions"><button className="lect-secondary" type="button" onClick={()=>window.location.reload()}>Cancel</button><button className="lect-primary">Save profile</button></div></form></Panel>; }
function SettingsPage({ theme, onToggleTheme, password, setPassword, act, logout }) { return <div className="lect-columns"><Panel title="Password and security"><form className="lect-form" onSubmit={e=>{e.preventDefault();act(async()=>{await lecturerRequest("/auth/password",sendJson("PATCH",password));setPassword({currentPassword:"",newPassword:""});},"Password changed.");}}><label>Current password<input type="password" autoComplete="current-password" required value={password.currentPassword} onChange={e=>setPassword({...password,currentPassword:e.target.value})}/></label><label>New password<input type="password" autoComplete="new-password" minLength="10" maxLength="72" required value={password.newPassword} onChange={e=>setPassword({...password,newPassword:e.target.value})}/></label><p className="lect-help">Use at least 10 characters. The existing authentication endpoint checks your current password.</p><button className="lect-primary">Change password</button></form></Panel><Panel title="Appearance and session"><p>Current theme: <b>{theme || "system"}</b></p><button className="lect-secondary" onClick={onToggleTheme}>Toggle application theme</button><hr/><p>Logout ends the current server session and clears the session cookie.</p><button className="lect-danger" onClick={logout}><LogOut size={15}/> Sign out</button><p className="lect-help">Notification preferences are not persisted in the current account model, so no unsaved preference controls are shown.</p></Panel></div>; }
